const fn = new Function(code + "\nreturn { makeStore };");
const { makeStore } = fn();
const store = makeStore();
const r1 = store.create({ title: "Ship it" }, "u1");
if (!r1.ok || r1.task.id !== "t1" || r1.task.ownerId !== "u1") throw new Error("First task t1 owned by u1.");
const r2 = store.create({ title: "Again" }, "u2");
if (r2.task.id !== "t2") throw new Error("Ids increment.");

const fn = new Function(code + "\nreturn { makeStore };");
const { makeStore } = fn();
const store = makeStore();
const bad = store.create({ title: "", due: "not-a-date" }, "u1");
if (bad.ok !== false) throw new Error("Invalid => ok false.");
if (bad.errors.length !== 2) throw new Error("Both errors collected.");
if (!bad.errors.some((e) => e.field === "title") || !bad.errors.some((e) => e.field === "due")) throw new Error("Each failing field named.");
